package org.sleepwell.app;

import org.junit.Test;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;

public class RhythmStatsTest {
    private final long now=Instant.parse("2026-11-10T12:00:00Z").toEpochMilli();
    private RecordEntry night(long id,String start,String end,String zone,String source){long a=Instant.parse(start).toEpochMilli(),b=Instant.parse(end).toEpochMilli();return new RecordEntry(id,a,b,null,source,"local",zone,0,0,new RecordDraft(a,b),false,0,List.of());}
    private RecordEntry n(long id,String date,int hour){LocalDate d=LocalDate.parse(date);long start=d.atTime(hour,0).toInstant(ZoneOffset.UTC).toEpochMilli(),end=start+8*3600000L;return new RecordEntry(id,start,end,null,"tracked","local","UTC",0,0,new RecordDraft(start,end),false,0,List.of());}
    @Test public void displayedGapMatchesRoundedClockEndpoints(){assertEquals(9*60000L,RhythmStats.displayGapMillis(174.4,182.9));assertEquals(0,RhythmStats.displayMinute(1439.6));assertEquals(2*60000L,RhythmStats.displayGapMillis(1439.6,2.4));assertEquals(2*60000L,RhythmStats.displayDurationMillis(1.5));}
    @Test public void midnightRangeUsesShortestArc(){assertEquals(10,RhythmStats.arc(List.of(1435d,5d))[1],.0001);assertEquals(0,RhythmStats.mean(List.of(1435d,5d)),.0001);}
    @Test public void antipodalMidpointsHaveNoRepresentativeMean(){assertNull(RhythmStats.mean(List.of(0d,720d)));assertNull(RhythmStats.mean(List.of()));}
    @Test public void circularDifferenceDoesNotTurnMidnightIntoTwentyThreeHours(){assertEquals(20,RhythmStats.distance(1430,10),.0001);}
    @Test public void emptyAndSingleNightDoNotInventVariabilityOrJetlag(){RhythmStats empty=new RhythmStats(List.of(),0,31,now);assertTrue(empty.recent.isEmpty());assertNull(empty.range);RhythmStats one=new RhythmStats(List.of(n(1,"2026-10-23",23)),0,31,now);assertNull(one.range);assertNull(one.jetlag);}
    @Test public void duplicateDaySelectsLongestThenNewestIdentity(){RecordEntry shortNight=n(1,"2026-10-23",23),longNight=n(2,"2026-10-23",22);shortNight.edit.end-=3600000;RecordEntry duplicate=new RecordEntry(3,longNight.rawStart,longNight.rawEnd,null,"tracked","local","UTC",0,0,longNight.edit,false,0,List.of());RhythmStats stats=new RhythmStats(List.of(shortNight,longNight,duplicate),0,31,now);assertEquals(1,stats.nights.size());assertEquals(3,stats.nights.get(0).record.id);assertEquals(1,stats.recorded);}
    @Test public void napsAndShortAndFutureAndOpenPeriodsAreExcluded(){RecordEntry nap=n(1,"2026-10-23",23);nap.edit.tags.add("Nap");RecordEntry shortOne=night(2,"2026-10-24T13:00:00Z","2026-10-24T14:00:00Z","UTC","tracked"),future=n(3,"2026-12-01",23);RecordEntry base=n(4,"2026-10-24",23),open=new RecordEntry(base.id,base.rawStart,0,null,"tracked","local","UTC",0,0,base.edit,false,0,List.of());assertTrue(new RhythmStats(List.of(nap,shortOne,future,open),0,31,now).nights.isEmpty());}
    @Test public void onlyLastSevenAvailableDatedNightsAreUsedAndGapsStayReal(){List<RecordEntry> records=new ArrayList<>();for(int day=1;day<=9;day++)records.add(n(day,"2026-10-"+String.format("%02d",day*2),22));RhythmStats stats=new RhythmStats(records,0,31,now);assertEquals(9,stats.recorded);assertEquals(7,stats.recent.size());assertEquals(LocalDate.of(2026,10,7),stats.recent.get(0).day);assertEquals(2,java.time.temporal.ChronoUnit.DAYS.between(stats.recent.get(0).day,stats.recent.get(1).day));}
    @Test public void manualEditsAffectPatternButNotRecordedEvidence(){RecordEntry manual=night(1,"2026-10-23T22:00:00Z","2026-10-24T06:00:00Z","UTC","manual");manual.edit.start+=3600000;RhythmStats stats=new RhythmStats(List.of(manual),0,31,now);assertEquals(1380,stats.recent.get(0).bedtime,.01);assertEquals(150,stats.recent.get(0).midpoint,.01);assertEquals(0,stats.recorded);}
    @Test public void effectiveAwakeTrimChangesPeriodBoundaries(){RecordEntry entry=n(1,"2026-10-23",22);entry.edit.awake.add(new RecordIntervals.Span(entry.edit.start,entry.edit.start+3600000));RhythmStats stats=new RhythmStats(List.of(entry),0,31,now);assertEquals(1380,stats.recent.get(0).bedtime,.01);assertEquals(150,stats.recent.get(0).midpoint,.01);}
    @Test public void midpointUsesElapsedInstantAcrossDstFold(){RecordEntry entry=night(1,"2026-10-24T22:00:00Z","2026-10-25T06:00:00Z","Europe/London","tracked");RhythmStats stats=new RhythmStats(List.of(entry),0,31,now);assertEquals(1380,stats.recent.get(0).bedtime,.01);assertEquals(120,stats.recent.get(0).midpoint,.01);}
    @Test public void workdayScheduleUsesWakeCalendarDayEvenWithNoonHistoryCutoff(){RecordEntry saturday=n(1,"2026-10-23",23);RhythmStats stats=new RhythmStats(List.of(saturday),720,31,now);assertEquals(LocalDate.of(2026,10,23),stats.recent.get(0).day);assertEquals(0,stats.workCount);assertEquals(1,stats.freeCount);}
    @Test public void actualWorkFreeMidpointsFollowSavedClassification(){RecordEntry work=n(1,"2026-10-22",22),free=n(2,"2026-10-23",23);RhythmStats stats=new RhythmStats(List.of(work,free),0,31,now);assertEquals(120,stats.workMidpoint,.01);assertEquals(180,stats.freeMidpoint,.01);assertEquals(60,stats.jetlag,.01);RhythmStats all=new RhythmStats(List.of(work,free),0,127,now);assertNull(all.jetlag);}
    @Test public void duplicatePhysicalIntervalAcrossZonesDoesNotAddEvidence(){RecordEntry utc=n(1,"2026-10-23",22),hawaii=new RecordEntry(2,utc.rawStart,utc.rawEnd,null,"tracked","local","Pacific/Honolulu",0,0,utc.edit,false,0,List.of());RhythmStats stats=new RhythmStats(List.of(utc,hawaii),0,31,now);assertEquals(1,stats.recorded);assertEquals(1,stats.nights.size());}
    @Test public void evidenceProgressCountsAllDistinctRecordedNightsBeyondVisibleSeven(){List<RecordEntry> entries=new ArrayList<>();for(int day=0;day<35;day++){LocalDate date=LocalDate.of(2026,10,1).plusDays(day);entries.add(n(day+1,date.toString(),22));}RhythmStats stats=new RhythmStats(entries,0,31,now);assertEquals(35,stats.recorded);assertEquals(7,stats.recent.size());}
}
